class Solution {
public:
    int minimumMoves(vector<vector<int>>& grid) {
        vector<pair<int, int>> zeros, extras;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (grid[r][c] == 0) zeros.push_back({r, c});
                else if (grid[r][c] > 1) {
                    for (int k = 0; k < grid[r][c] - 1; k++) extras.push_back({r, c});
                }
            }
        }
        int ans = 1e9;
        sort(extras.begin(), extras.end());
        do {
            int curr = 0;
            for (int i = 0; i < zeros.size(); i++) {
                curr += abs(zeros[i].first - extras[i].first) + abs(zeros[i].second - extras[i].second);
            }
            ans = min(ans, curr);
        } while (next_permutation(extras.begin(), extras.end()));
        return ans;
    }
};

class Solution {
    private int ans = Integer.MAX_VALUE;
    public int minimumMoves(int[][] grid) {
        List<int[]> zeros = new ArrayList<>();
        List<int[]> extras = new ArrayList<>();
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (grid[r][c] == 0) zeros.add(new int[]{r, c});
                else if (grid[r][c] > 1) {
                    for (int k = 0; k < grid[r][c] - 1; k++) extras.add(new int[]{r, c});
                }
            }
        }
        boolean[] used = new boolean[extras.size()];
        permute(zeros, extras, used, 0, 0);
        return ans;
    }
    private void permute(List<int[]> zeros, List<int[]> extras, boolean[] used, int idx, int curr) {
        if (idx == zeros.size()) {
            ans = Math.min(ans, curr);
            return;
        }
        int[] z = zeros.get(idx);
        for (int i = 0; i < extras.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                int[] e = extras.get(i);
                int cost = Math.abs(z[0] - e[0]) + Math.abs(z[1] - e[1]);
                permute(zeros, extras, used, idx + 1, curr + cost);
                used[i] = false;
            }
        }
    }
}

/**
 * @param {number[][]} grid
 * @return {number}
