var minimumMoves = function(grid) {
    const zeros = [];
    const extras = [];
    for (let r = 0; r < 3; r++) {
        for (let c = 0; c < 3; c++) {
            if (grid[r][c] === 0) zeros.push([r, c]);
            else if (grid[r][c] > 1) {
                for (let k = 0; k < grid[r][c] - 1; k++) extras.push([r, c]);
            }
        }
    }
    let ans = Infinity;
    const used = new Uint8Array(extras.length);
    function backtrack(idx, cost) {
        if (idx === zeros.length) {
            if (cost < ans) ans = cost;
            return;
        }
        const [zr, zc] = zeros[idx];
        for (let i = 0; i < extras.length; i++) {
            if (!used[i]) {
                used[i] = 1;
                const [er, ec] = extras[i];
                const d = Math.abs(zr - er) + Math.abs(zc - ec);
                backtrack(idx + 1, cost + d);
                used[i] = 0;
            }
        }
    }
    backtrack(0, 0);
    return ans;
};
